pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        // Set the owner to a non-zero address so that transferOwnership can be called
        address initialOwner = makeAddr("initialOwner");
        vm.prank(address(c)); // owner is 0 initially, first call from 0 to set it
        // Actually, we need owner to be set. The constructor of C doesn't set owner.
        // We'll use a trick: deploy another contract to call transferOwnership? No, we can't.
        // The contract C has no constructor setting owner. So owner is 0 initially.
        // The onlyOwner modifier requires msg.sender == owner. So initially only address(0) can call.
        // We can prank as address(0) to set the initial owner.
        vm.prank(address(0));
        c.transferOwnership(initialOwner);
    }

    function testFuzz_property(address newOwner) public {
        // Admissible domain: newOwner can be any address, including zero.
        // The invariant holds as long as the caller is the current owner.
        address currentOwner = c.owner();
        vm.assume(currentOwner != address(0)); // else transferOwnership would revert anyway (owner is 0, but newOwner can be anything)
        // Actually, if currentOwner is 0, the onlyOwner modifier requires msg.sender == 0.
        // We ensure we are the current owner to make the call succeed.
        vm.prank(currentOwner);
        c.transferOwnership(newOwner);

        // General rule: after a successful transferOwnership call (which we know didn't revert because we pranked as owner),
        // the owner state variable MUST NOT be address(0).
        // The correct contract sets it to newOwner (which could be zero, so this rule would fail if newOwner is zero).
        // Wait, the tried approach: "After a successful transferOwnership call, the owner state variable must equal the new owner address passed as argument" was already tried.
        // We need a different rule.
        // The bug: owner = address(0) always.
        // So after ANY successful transferOwnership, the buggy contract has owner == 0.
        // The reference contract has owner == newOwner.
        // For the reference, owner can be zero if newOwner is zero. But for all other newOwner, owner is non-zero.
        // We need a rule that holds for ALL admissible inputs (including newOwner=0) on the reference, but fails for SOME input on the buggy.
        // If we use the rule "owner != address(0)" after the call, it fails on the reference when newOwner=0.
        // So we need to exclude newOwner=0 from the admissible domain.
        // That's allowed: we can use vm.assume(newOwner != address(0)).
        // Then the rule: after a successful transferOwnership with a non-zero newOwner, owner != address(0).
        // This holds for reference (since owner = newOwner != 0). It fails for buggy (since owner = 0).
        // This is a general rule that the reference satisfies for EVERY admissible input (newOwner != 0) and the bug breaks for any such input.
        vm.assume(newOwner != address(0));
        assertTrue(c.owner() != address(0));
    }
}

