import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        vm.assume(newOwner != address(this));
        // The initial owner is address(this) because C() sets owner to msg.sender (this).
        // Transfer ownership to newOwner so the initial owner is no longer the owner.
        c.transferOwnership(newOwner);
        // Now the original owner is address(this). Under the reference contract,
        // ownership was given to newOwner, so a call from this (old owner) to
        // transferOwnership should revert (onlyOwner fails). Under the buggy contract,
        // owner was set to address(0), so the same call also reverts.
        // But we need the bug to produce a different observable outcome.
        // Choose a different call: the old owner tries to call owned() which does nothing
        // but is guarded by onlyOwner. In reference, old owner's call reverts;
        // in bug, owner is address(0), so any call by non-zero address reverts too.
        //
        // Instead, consider the invariant: after a transfer, the current owner can
        // successfully call an onlyOwner function. The bug sets owner to address(0),
        // so even if newOwner tries to call an onlyOwner function, it reverts.
        // Let's assert that newOwner can successfully call owned().
        vm.prank(newOwner);
        try c.owned() {
            // Reference: owner is newOwner, call succeeds.
            // Bug: owner is address(0), call reverts.
            assertTrue(true);
        } catch {
            // Bug will enter this catch block.
            assertTrue(false);
        }
    }
}

